class FeCAM(BaseLearner):
    def __init__(self, args):
        super().__init__(args)
        self.args = args
        self._network = CosineIncrementalNet(args, False)
        self._protos = []
        self._init_protos = []
        self._common_cov = None
        self._cov_mat = []
        self._diag_mat = []
        self._common_cov_shrink = None
        self._cov_mat_shrink = []
        self._norm_cov_mat = []

    def _train(self, train_loader, test_loader):
        # For FeCAM, the _train method orchestrates prototype and covariance matrix computation
        # after initial task 0 training, which is handled by _train_function (standard supervised training).
        # The key logic for FeCAM-specific techniques (covariance, Mahalanobis) is in _build_protos and
        # the conditional blocks for full_cov/diagonal.
        if self._cur_task > 0:
            self._cov_mat_shrink, self._norm_cov_mat, self._diag_mat = [], [], []
            self._network.to(self._device)
            if hasattr(self._network, "module"):
                self._network_module_ptr = self._network.module
            self._build_protos() # Computes class mean prototypes (µy)
            # self._update_fc() # Updates classifier head; not directly Mahalanobis-related
            if self.args["full_cov"]:
                if self.args["per_class"]:
                    compute_new_cov(self) # Computes class-specific covariance matrices (Σy)
                    if self.args["shrink"]:
                        for cov in self._cov_mat:
                            self._cov_mat_shrink.append(self.shrink_cov(cov)) # Apply Covariance Shrinkage
                    if self.args["norm_cov"]:
                        self._norm_cov_mat = self.normalize_cov() # Apply Correlation Normalization
                else:
                    self._common_cov = compute_new_common_cov(train_loader, self) # Computes common covariance
            elif self.args["diagonal"]:
                if self.args["per_class"]:
                    compute_new_cov(self)
                    for cov in self._cov_mat:
                        self._cov_mat_shrink.append(self.shrink_cov(cov))
                    for cov in self._cov_mat_shrink:
                        cov = self.normalize_cov2(cov) # Apply a different normalization for diagonal
                        self._diag_mat.append(self.diagonalization(cov)) # Approximate with diagonal matrix

    def _build_protos(self):
        # Extracts features and computes class mean prototypes (µy) for current classes
        with torch.no_grad():
            for class_idx in range(self._known_classes, self._total_classes):
                data, targets, idx_dataset = self.data_manager.get_dataset(np.arange(class_idx, class_idx+1), source='train',
                                                                    mode='test', shot=self.shot, ret_data=True)
                idx_loader = DataLoader(idx_dataset, batch_size=self.args["batch_size"], shuffle=False, num_workers=4)
                vectors, _ = self._extract_vectors(idx_loader)
                class_mean = np.mean(vectors, axis=0)
                self._protos.append(torch.tensor(class_mean).to(self._device))


class BaseLearner(object):
    # This class (from models/base.py) contains core Mahalanobis distance logic and covariance transformations.

    def _eval_maha(self, loader, init_means, class_means):
        # Evaluates classification using Mahalanobis distance
        self._network.eval()
        vectors, y_true = self._extract_vectors(loader)
        vectors = (vectors.T / (np.linalg.norm(vectors.T, axis=0) + EPSILON)).T # L2-normalize feature vectors

        dists = self._maha_dist(vectors, init_means, class_means)
        scores = dists.T
        return np.argsort(scores, axis=1)[:, : self.topk], y_true

    def _maha_dist(self, vectors, init_means, class_means):
        # Computes Mahalanobis distance to each class prototype
        vectors = torch.tensor(vectors).to(self._device)
        if self.args["tukey"] and self._cur_task > 0:
            vectors = self._tukeys_transform(vectors) # Apply Tukey’s Ladder of Powers Transformation to features
        maha_dist = []
        for class_index in range(self._total_classes):
            if self._cur_task == 0:
                dist = self._mahalanobis(vectors, init_means[class_index])
            else:
                # Selects the appropriate covariance matrix based on configuration
                if self.args["full_cov"]:
                    if self.args["per_class"]:
                        if self.args["norm_cov"]:
                            cov_to_use = self._norm_cov_mat[class_index]
                        elif self.args["shrink"]:
                            cov_to_use = self._cov_mat_shrink[class_index]
                        else:
                            cov_to_use = self._cov_mat[class_index]
                    else:
                        cov_to_use = self._common_cov
                elif self.args["diagonal"]:
                    cov_to_use = self._diag_mat[class_index]
                else: # Fallback for NCM (Euclidean distance, identity covariance)
                    cov_to_use = None
                dist = self._mahalanobis(vectors, class_means[class_index], cov_to_use)
            maha_dist.append(dist)
        maha_dist = np.array(maha_dist)
        return maha_dist

    def _mahalanobis(self, vectors, class_means, cov=None):
        # Core Mahalanobis distance calculation: d(x, µ) = sqrt((x-µ)T Σ-1 (x-µ))
        if self.args["tukey"] and self._cur_task > 0:
            class_means = self._tukeys_transform(class_means) # Apply Tukey’s Transformation to class means
        # Subtract mean and L2-normalize (˜ϕ(x) - µy)
        x_minus_mu = F.normalize(vectors, p=2, dim=-1) - F.normalize(class_means, p=2, dim=-1)
        if cov is None:
            cov = torch.eye(self._network.feature_dim) # Identity matrix for Euclidean distance (NCM)
        inv_covmat = torch.linalg.pinv(cov).float().to(self._device) # Pseudo-inverse of covariance matrix
        left_term = torch.matmul(x_minus_mu, inv_covmat)
        mahal = torch.matmul(left_term, x_minus_mu.T)
        return torch.diagonal(mahal, 0).cpu().numpy()

    def diagonalization(self, cov):
        # Extracts the diagonal elements of a covariance matrix to approximate it as a diagonal matrix
        diag = cov.clone()
        cov_ = cov.clone()
        cov_.fill_diagonal_(0.0)
        diag = diag - cov_
        return diag

    def shrink_cov(self, cov):
        # Implements Covariance Shrinkage: Σs = Σ + α1*mean(diag(Σ))*I + α2*mean(off-diag(Σ))*(1-I)
        diag_mean = torch.mean(torch.diagonal(cov))
        off_diag = cov.clone()
        off_diag.fill_diagonal_(0.0)
        mask = off_diag != 0.0
        off_diag_mean = (off_diag*mask).sum() / mask.sum()
        iden = torch.eye(cov.shape[0])
        alpha1 = self.args["alpha1"]
        alpha2  = self.args["alpha2"]
        cov_ = cov + (alpha1*diag_mean*iden) + (alpha2*off_diag_mean*(1-iden))
        return cov_

    def normalize_cov(self):
        # Applies Correlation Normalization to covariance matrices
        if self.args["shrink"]:
            cov_mat = self._cov_mat_shrink
        else:
            cov_mat = self._cov_mat
        norm_cov_mat = []
        for cov in cov_mat:
            sd = torch.sqrt(torch.diagonal(cov)) # Standard deviations
            cov = cov/(torch.matmul(sd.unsqueeze(1),sd.unsqueeze(0))) # Divide by outer product of standard deviations
            norm_cov_mat.append(cov)
        return norm_cov_mat    

    def normalize_cov2(self, cov):
        # An alternative covariance normalization method
        diag = torch.diagonal(cov)
        norm = torch.linalg.norm(diag)
        cov = cov /norm
        return cov

    def _tukeys_transform(self, x):
        # Implements Tukey’s Ladder of Powers Transformation to make features more Gaussian-like
        beta = self.args["beta"]
        x = torch.tensor(x)
        if beta == 0:
            return torch.log(x)
        else:
            return torch.pow(x, beta)

    def _extract_vectors(self, loader):
        # Helper to extract L2-normalized feature vectors from the network backbone
        self._network.eval()
        vectors, targets = [], []
        for _, _inputs, _targets in loader:
            _targets = _targets.numpy()
            # Assumes _network is a DataParallel model or has a .module attribute
            _vectors = tensor2numpy(self._network.module.extract_vector(_inputs.to(self._device)))
            vectors.append(_vectors)
            targets.append(_targets)
        return np.concatenate(vectors), np.concatenate(targets)

def compute_new_cov(model):
    # Utility function (from utils/maha_utils.py) to compute class-specific covariance matrices
    for class_idx in range(model._known_classes, model._total_classes):
        data, targets, idx_dataset = model.data_manager.get_dataset(np.arange(class_idx, class_idx+1), source='train',
                                                                mode='test', ret_data=True)
        idx_loader = DataLoader(idx_dataset, batch_size=model.args["batch_size"], shuffle=False, num_workers=4)
        vectors, _ = model._extract_vectors(idx_loader)
        if model.args["tukey"]:
            vectors = model._tukeys_transform(vectors) # Apply Tukey's transform before covariance calculation

        cov = torch.tensor(np.cov(vectors.T)) # Compute empirical covariance matrix
        if model.args["shrink"]:
            cov = model.shrink_cov(cov) # Apply shrinkage immediately

        model._cov_mat.append(cov)

def compute_new_common_cov(train_loader, model):
    # Utility function (from utils/maha_utils.py) to compute a common covariance matrix for all classes
    # This version averages with previous common covariance for continual learning.
    if model.args["dataset"] == 'imagenet100':
        cov = model._extract_vectors_common_cov(train_loader)
    else:
        vectors, _ = model._extract_vectors(train_loader)
        if model.args["tukey"]:
            vectors = model._tukeys_transform(vectors)
        cov = torch.tensor(np.cov(vectors.T))
    if model.args["shrink"]:
        cov = model.shrink_cov(cov)
    ratio = (model._known_classes/model._total_classes)
    common_cov = ratio*model._common_cov + (1-ratio)*cov
    return common_cov
